**面向过程地实现多态**（std::bind + std::function）：

```cpp
#include <iostream>
#include <functional>
#include <math.h>

using std::cout;
using std::endl;
using std::bind;
using std::function;

class Figure {
    // 回调函数的设计思想
public:
    using DisplayCallBack = function<void()>;
    using AreaCallBack = function<double()>;

    DisplayCallBack _displayCallBack;
    AreaCallBack _areaCallBack;

    // 回调函数的注册
    void setDisplayCallBack(DisplayCallBack&& cb)
    {
        _displayCallBack = std::move(cb);
    }

    void setAreaCallBack(AreaCallBack&& cb)
    {
        _areaCallBack = std::move(cb);
    }

    // 回调函数的执行
    void handleDisplayCallBack() const 
    {
        if(_displayCallBack)
        {
            _displayCallBack();
        }
    }

    double handleAreaCallBack() const
    {
        if(_areaCallBack) {
            return _areaCallBack();
        }
        else {
            return 0.0;
        }
    }
};

class Rectangle {
public:
    Rectangle(double length = 0, double width = 0)
    :_length(length), _width(width) {
        cout << "Rectangle(double, double)" << endl;
    }

    void display() const {
        cout << "Rectangle";
    }

    double area() const {
        return _length*_width;
    }

    ~Rectangle() {
        cout <<"~Rectangle()" <<endl;
    }

private:
    double _length;
    double _width;
};

class Circle {
public:
    Circle(double radius = 0):_radius(radius) {
        cout << "Circle(double = 0)" <<endl;
    }

    void display() const {
        cout << "Circle";
    }

    double area() const {
        return 3.14 * _radius * _radius;
    }

    ~Circle() {
        cout <<"~Circle()" <<endl;
    }
private:
    double _radius;
};

class Triangle {
public:
    Triangle(double a = 0, double b= 0, double c = 0)
    : _a(a), _b(b), _c(c) {
        cout << "Triangle(double = 0, double = 0, double = 0)" <<endl;
    }

    void display() const {
        cout << "Triangle";
    }

    double area() const {
        double tmp = (_a + _b + _c)/2;
        return sqrt(tmp*(tmp-_a)*(tmp-_b)*(tmp-_c));
    }

    ~Triangle() {
        cout << "~Triangle()" << endl;
    }

private:
    double _a;
    double _b;
    double _c;
};

void func(const Figure& fig) {
    fig.handleDisplayCallBack();
    cout << "的面积：" << fig.handleAreaCallBack() <<endl;
}

int main() {
    Rectangle rectangle(10, 20);
    Circle circle(10);
    Triangle triangle(3, 4, 5);

    // Figure 是具体的类
    Figure fig;
    fig.setDisplayCallBack(bind(&Rectangle::display, &rectangle));
    fig.setAreaCallBack(bind(&Rectangle::area, &rectangle));
    func(fig);

    fig.setDisplayCallBack(bind(&Circle::display, &circle));
    fig.setAreaCallBack(bind(&Circle::area, &circle));
    func(fig);

    fig.setDisplayCallBack(bind(&Triangle::display, &triangle));
    fig.setAreaCallBack(bind(&Triangle::area, &triangle));
    func(fig);

    return 0;
}
/*
Rectangle(double, double)
Circle(double = 0)
Triangle(double = 0, double = 0, double = 0)
Rectangle的面积：200
Circle的面积：314
Triangle的面积：6
~Triangle()
~Circle()
~Rectangle()
*/
```

