### 实现自己的 vector

整体逻辑不算难，但是很多细节弄不出来，很麻烦。

```cpp
#include <iostream>
#include <memory>
#include <algorithm>

using std::cout;
using std::endl;

template<typename T>
class Vector
{
public:
    using iterator = T*;
    Vector()
    : _start(nullptr)
    , _finish(nullptr)
    , _end_of_storage(nullptr) {}

    iterator begin() const {
        return _start;
    }

    iterator begin() {
        return _start;
    }

    iterator end() const {
        return _finish;
    }

    iterator end() {
        return _finish;
    }

    ~Vector();
    void push_back(const T& value); 
    void pop_back();    
    int size() const;
    int capacity() const;

private:
    void reallocate(); //重新分配内存,动态扩容要用的

    static std::allocator<T> _alloc;

    T *_start;                 //指向数组中的第一个元素
    T *_finish;                //指向最后一个实际元素之后的那个元素
    T *_end_of_storage;        //指向数组本身之后的位置
};

template <typename T>
std::allocator<T> Vector<T>::_alloc; // 静态数据成员进行初始化

template <typename T>
Vector<T>::~Vector()
{
    if(_start) {
        while(_finish != _start) {
            // 销毁空间上的元素
            _alloc.destroy(--_finish);
        }
        // 回收空间
        _alloc.deallocate(_start, capacity());
    }
}

template <typename T>
void Vector<T>::push_back(const T& value)
{
    if(size() == capacity())
    {
        reallocate();
    }
    _alloc.construct(_finish++, value);
}

template <typename T>
void Vector<T>::pop_back()
{
    if(size() <= 0) return;
    _alloc.destroy(--_finish);
}

template <typename T>
int Vector<T>::size() const
{
    return _finish - _start;
}

template <typename T>
int Vector<T>::capacity() const
{
    return _end_of_storage - _start;
}

template <typename T>
void Vector<T>::reallocate()
{
    int oldCapacity = capacity();
    int newCapacity = 2*oldCapacity > 0 ? 2*oldCapacity : 1;
    T* tmp = _alloc.allocate(newCapacity);

    if(_start) {
        // 拷贝老空间上的元素到新空间
        std::uninitialized_copy(_start, _finish, tmp);
        while(_finish != _start) {
            // 销毁老空间上的元素
            _alloc.destroy(--_finish);
        }
        // 回收老的空间
        _alloc.deallocate(_start, capacity());
    }
    _start = tmp;
    _finish = _start + oldCapacity;
    _end_of_storage = _start + newCapacity;
}

template <typename Container>
void printinfo(const Container& con)
{
    cout << "con.size() = " << con.size() << endl
         << "con.capacity() = " << con.capacity() << endl;
}

