### 抽象工厂

在软件开发及运行过程中，经常面临着“一系列相互依赖的对象”的创建工作；而由于需求的变化，常常存在更多系列对象的创建问题。

做法是：提供一个接口，该接口负责创建一系列“相关或者相互依赖的对象”，无需指定它们具体的类。

![74-8.png](https://s2.loli.net/2024/05/11/2d6vpxyYeOc3rUH.png)

参考代码：

```cpp
//A类型的抽象产品
class AbstractProductA
{
public:
    virtual void show() = 0;
    ~AbstractProductA(){}
};

//B类型的抽象产品
class AbstractProductB
{
public:
    virtual void show() = 0;
    ~AbstractProductB(){}
};

class ProductA1
: public AbstractProductA
{
public:
    virtual void show() override
    {
        cout << "void ProductA1::show()" << endl;
    }
};

class ProductA2
: public AbstractProductA
{
public:
    virtual void show() override
    {
        cout << "void ProductA2::show()" << endl;
    }
};

class ProductB1
: public AbstractProductB
{
public:
    virtual void show() override
    {
        cout << "void ProductB1::show()" << endl;
    }
};

class ProductB2
: public AbstractProductB
{
public:
    virtual void show() override
    {
        cout << "void ProductB2::show()" << endl;
    }
};

class AbstractFactory
{
public:
    virtual AbstractProductA *createProductA() = 0;
    virtual AbstractProductB *createProductB() = 0;
    ~AbstractFactory() {}
};

class ConcreteFactory1
: public AbstractFactory
{
public:
    AbstractProductA *createProductA() override
    {
