### 线程的退出

```cpp
#include <pthread.h>
void pthread_exit(void *retval);
//retVal:线程退出时候的值（状态）
```

示例：

```cpp
#include <pthread.h>
#include <unistd.h>
#include <iostream>
#include <string.h>

#define ERROR_CHECK(msg, ret) \
        do{                   \
            printf("%s: %s\n", msg, strerror(ret)); \
        }while(0);

void* threadFunc(void* arg) {
    int* pInt = (int*)arg;
    printf("I'm a child thread. %d\n", *pInt);

    pthread_exit(nullptr);
}

int main() {
    pthread_t thid;
    int aaa = 10;
    int ret = pthread_create(&thid, nullptr, threadFunc, (void*)&aaa);
    ERROR_CHECK("pthread_create", ret);

    usleep(100);
    printf("I'm a main thread.\n");
    return 0;
}
/*
pthread_create: Success
I'm a child thread. 10
I'm a main thread.
*/
```

main 线程是主线程，主线程执行完毕之后，不管子线程，子线程有可能还没有来得及执行。所以一般都需要让主线程等待子线程执行完毕，再退出。

### 线程的等待

```cpp
int pthread_join(pthread_t thread, void **retval);
//thread：传递进来的是被等待线程的id
//retVal：将等待线程的状态值取出来
```

示例：

```cpp
#include <pthread.h>
#include <unistd.h>
#include <iostream>
#include <string.h>

#define ERROR_CHECK(msg, ret) \
        do{                   \
            printf("%s: %s\n", msg, strerror(ret)); \
        }while(0);

void* threadFunc(void* arg) {
    printf("I'm a child thread.\n");
    pthread_exit(nullptr);
}

int main() {
    pthread_t thid;
    int ret = pthread_create(&thid, nullptr, threadFunc, nullptr);
    ERROR_CHECK("pthread_create", ret);

    ret = pthread_join(thid, nullptr);
    ERROR_CHECK("pthread_join", ret);

    printf("I'm a main thread.\n");
    return 0;
}
/*
pthread_create: Success
I'm a child thread.
pthread_join: Success
I'm a main thread.
*/
```

获取线程 id：

```cpp
pthread_t pthread_self(void);
```

线程的执行具有随机性。因为时序不同，所以每次运行的结果都可能不同。

### 线程的取消

```cpp
int pthread_cancel(pthread_t thread);
//thread:被取消的线程id
```

线程也可以被其它线程杀掉，在 Linux 中的说法是一个线程被另一个线程取消（cancel）。

线程取消的方法是一个线程向目标线程发 cancel 信号， 但是如何处理 cancel 信号则由目标线程自己决定，目标线程或者忽略、或者立即终止、或者继续运行至 cancelation-point（取消点）后终止。**默认的行为是运行到取消点。**

根据 POSIX 标准：一些会引起阻塞的系统调用都是取消点。不过经过测试一些非阻塞性函数也可以是取消点。可以通过 man 7 pthreads 查看，不过由于 Linux 线程库和 C 库结合的不是很好，有很多函数没有明确是否为取消点。

总之，线程的取消一方面是一个线程强行杀另外一个线程，从程序设计角度看并不是一种好的风格，另一方面目前 Linux 本身对这方面的支持并不完善，所以在**实践中应该谨慎使用**。

```cpp
#include <pthread.h>
#include <unistd.h>
#include <iostream>
#include <string.h>

#define ERROR_CHECK(msg, ret) \
        do{                   \
            printf("%s: %s\n", msg, strerror(ret)); \
        }while(0);

void* threadFunc(void* arg) {
    usleep(100);
    printf("I'm a child thread.\n");
    pthread_exit(nullptr);
}

int main() {
    pthread_t thid;
    int ret = pthread_create(&thid, nullptr, threadFunc, nullptr);
    ERROR_CHECK("pthread_create", ret);

    // 主线程尝试杀死子线程
    ret = pthread_cancel(thid);
    ERROR_CHECK("pthread_cancel", ret);

    ret = pthread_join(thid, nullptr);
    ERROR_CHECK("pthread_join", ret);

    printf("I'm a main thread.\n");
    return 0;
}
/*
pthread_create: Success
pthread_cancel: Success
pthread_join: Success
I'm a main thread.
*/
```

### 线程的分离

如果想让主线程不去等待或者回收子线程，那么可以将子线程设置为分离状态：

```cpp
int pthread_detach(pthread_t thread);
```

## 面向对象的线程封装

整体思路：

![74-10.png](https://bu.dusays.com/2024/05/13/6641e4a61deff.png)

``Thread.h``：

```cpp
#ifndef __THREAD_H__
#define __THREAD_H__

#include <pthread.h>

class Thread {
public:
    Thread();
    virtual ~Thread();
    void start();
    void join();

private:
    static void* threadFunc(void* arg); // 线程的入口函数
    virtual void run() = 0;      // 线程的执行任务

    pthread_t _thid;  // 线程 id
    bool _isRunning; // 线程运行的标志位
};

#endif
```

``Thread.cc``：

```cpp
#include "Thread.h"
#include <stdio.h>

Thread::Thread()
: _thid(0)
, _isRunning(false)
{
}

Thread::~Thread()
{
    if(_isRunning)
    {
        // 让子线程与主线程分离，主线程不管子线程的回收
        pthread_detach(_thid);
        _isRunning = false;
    }
}

// 线程，启动！
void Thread::start()
{
    int ret = pthread_create(&_thid, nullptr, threadFunc, this);
    if(ret)
    {
        perror("pthread_create\n");
        return;
    }
    _isRunning = true;
}

void Thread::join()
{
    if(_isRunning)
    {
        int ret = pthread_join(_thid, nullptr);
        if(ret)
        {
            perror("pthread_join\n");
            return;
        }
        _isRunning = false;
    }
}

void* Thread::threadFunc(void* arg)
{
    Thread* pth = static_cast<Thread*>(arg);
    if(pth)
    {
        // threadFunc 是 static 的，没有 this 指针
        // 故在 pthread_create 中将 this 传进来
        pth->run(); // 体现多态
    }
    // 让子线程主动退出
    pthread_exit(nullptr);
}
```

``testThread.cc``：

```cpp
#include "Thread.h"
#include <iostream>
#include <memory>
#include <unistd.h>

using std::unique_ptr;

class MyThread: public Thread
{
private:
    void run() override
    {
        // 具体逻辑根据需要书写
        while(1){
        std::cout << "My Thread is Running !" << std::endl;
        sleep(1);
        }
    }
};

int main() {
    unique_ptr<Thread> p(new MyThread());
    p->start();
    p->join();
    return 0;
}
```

## 基于对象的线程封装

思路：

![74-11.jpg](https://s2.loli.net/2024/05/14/NYAtgceWVFSXHMR.jpg)

``Thread.h`` :

```cpp
#ifndef __THREAD_H__
#define __THREAD_H__

#include <pthread.h>
#include <functional>

using std::function;

class Thread {
    using ThreadCallBack = function<void()>;
public:
    Thread(ThreadCallBack&& cb); // 移动语义是为了提高效率
    ~Thread();
    void start();
    void join();

private:
    static void* threadFunc(void* arg); // 线程的入口函数

    pthread_t _thid;     // 线程 id
    bool _isRunning;     // 线程运行的标志位
    ThreadCallBack _cb;  // 封装的任务
};

#endif
```

``Thread.cc`` :

```cpp
#include "Thread.h"
#include <stdio.h>

Thread::Thread(ThreadCallBack&& cb)
: _thid(0)
, _isRunning(false)
, _cb(std::move(cb)) // 注册回调函数
{
}

Thread::~Thread()
{
    if(_isRunning)
    {
        // 让子线程与主线程分离，主线程不管子线程的回收
        pthread_detach(_thid);
        _isRunning = false;
    }
}

// 线程，启动！
void Thread::start()
{
    int ret = pthread_create(&_thid, nullptr, threadFunc, this);
    if(ret)
    {
        perror("pthread_create\n");
        return;
    }
    _isRunning = true;
}

void Thread::join()
{
    if(_isRunning)
    {
        int ret = pthread_join(_thid, nullptr);
        if(ret)
        {
            perror("pthread_join\n");
            return;
        }
        _isRunning = false;
    }
}

void* Thread::threadFunc(void* arg)
{
    Thread* pth = static_cast<Thread*>(arg);
    if(pth)
    {
        // threadFunc 是 static 的，没有 this 指针
        // 故在 pthread_create 中将 this 传进来
        pth->_cb();  // 执行回调函数
    }
    // 让子线程主动退出
    pthread_exit(nullptr);
}
```

``testThread.cc`` :

