    data.num = 0;

    // 互斥锁初始化
    int ret = pthread_mutex_init(&data.mutex, nullptr);
    ERROR_CHECK("pthread_mutex_init", ret);

    // 条件变量初始化
    ret = pthread_cond_init(&data.cond, nullptr);
    ERROR_CHECK("pthread_cond_init", ret);

