### 利用 RAII 优化

一个小改进，我们可以利用 RAII 的思想管理锁（以两个文件为例）：

``MutexLock.h`` :

```cpp
#ifndef _MUTEXLOCK_H_
#define _MUTEXLOCK_H_

#include <pthread.h>

class MutexLock
{
public:
    MutexLock();
    ~MutexLock();
    void lock();
    void trylock();
    void unlock();

    pthread_mutex_t* get_mutex_ptr()
    {
        return &_mutex;
    }

private:
    pthread_mutex_t _mutex;
};

// 利用 RAII 的思想
class MutexLockGuard
{
public:
    MutexLockGuard(MutexLock& mutex)
    : _mutex(mutex)
    {
        _mutex.lock();
    }

    ~MutexLockGuard()
    {
        _mutex.unlock();
    }

private:
    MutexLock& _mutex;
};

#endif
```

``TaskQueue.cc`` :

```cpp
#include "TaskQueue.h"

TaskQueue::TaskQueue(size_t queSize)
: _queSize(queSize)
, _que()
, _mutex()
, _notEmpty(_mutex)
, _notFull(_mutex)  // 注意要按照顺序初始化
{
}

// _queSize 和 _que 不用管
// _mutex, _notEmpty, _notFull 生命周期结束自动执行各自的析构函数
TaskQueue::~TaskQueue() = default;

bool TaskQueue::empty() const
{
    return 0 == _que.size();
}

bool TaskQueue::full() const
{
    return _que.size() == _queSize;
    // 这里的 _queSize 其实是指队列的最大容量
}

void TaskQueue::push(const int& value)
{
    // RAII 的思想：
    // 在构造函数中初始化资源，析构函数中释放
    // 实质：用栈对象的生命周期管理资源
    MutexLockGuard autolock(_mutex);

    if(full())
    {
        _notFull.wait();
        // 这个变量命名有点奇怪，可以这样理解：
        // 等待不满的时候
    }

    _que.push(value);
    _notEmpty.notify(); // 唤醒消费者
}

int TaskQueue::pop()
{
    MutexLockGuard autolock(_mutex);

    if(empty())
    {
        _notEmpty.wait();
    }

    int tmp = _que.front();
    _que.pop();
    _notFull.notify(); // 唤醒生产者
    return tmp;
}
