fds[1024]   fds[0].fd = listendfd;   fds[0].events = POLLIN;

struct pollfd
{
    int fd;   /* file descriptor */
    short events; /* requested events *///监听的事件类型，读事件，写事件，异常
    short revents;/* returned events */
};
