### epoll

epoll 是 Linux 下 IO 多路复用接口 select/poll 的增强版本，能显著提高程序在**大量并发连接中只有少量活跃**的情况下的系统 CPU 利用率，因为它会复用文件描述符集合来传递结果而不是迫使开发者每次等待事件之前都必须重新准备要侦听的文件描述符集合，另一个原因是获取事件的时候，它**无须遍历整个被侦听的描述符集，只要遍历哪些被内核 IO 事件唤醒而加入 Ready 队列的描述符集合**就行了。

```c
#include <sys/epoll.h>
int epoll_create(int size);
//size:linux内核版本2.6.8之后，size可以忽略，但是要大于0
//返回值：成功返回非负整数，失败返回-1.
int epoll_create1(int flags);

#include <sys/epoll.h>
int epoll_ctl(int epfd, int op, int fd, struct epoll_event *event);
//epfd:是epoll_create函数的返回值，也就是文件描述符
//op:EPOLL_CTL_ADD/EPOLL_CTL_MOD/EPOLL_CTL_DEL
//fd:将哪个文件描述符以op的方式加在以epfd建立的树上
//event:告诉内核需要监听的事情,EPOLLIN/EPOLLOUT/EPOLLERR/...
struct epoll_event
{
    uint32_t events;   /* Epoll events */
    epoll_data_t data; /* User data variable */
};

typedef union epoll_data
{
    void     *ptr;  // 拓展性
    int       fd;
    uint32_t  u32;
    uint64_t  u64;
} epoll_data_t;


struct A  // 例如我们用 void* ptr 指向这个结构体
{
    int number;
    void* (pFunc)(void *);
};

#include <sys/epoll.h>
int epoll_wait(int epfd, struct epoll_event *events, int maxevents, int timeout);
//epfd:是epoll_create函数的返回值，也就是文件描述符
//events:满足条件的事件都在该结构体，只需遍历该结构体即可
//maxevents：告知内核这个events有多大.
//timeout 毫秒级等待
//-1:阻塞等，#define INFTIM -1 Linux中没有定义此宏
//0:立即返回，不阻塞进程
//>0:等待指定毫秒数，如当前系统时间精度不够毫秒，向上取值。

//返回值：成功，将满足条件的文件描述符的个数返回；失败就返回-1.
```

epoll 中涉及到两个数据结构： epoll_create 创建的红黑树的根节点，将满足条件的事件放在就绪链表，可以直接遍历就绪链表即可。

![74-21.png](https://s2.loli.net/2024/05/24/Wozj7Qm2pLcMaNV.png)

代码（**下面两份代码没有实际运行验证**）：

```c
// server.c
#include <stdio.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/epoll.h>
#include <stdlib.h>
#include <strings.h>
#include <unistd.h>
#include <ctype.h>

#define SERV_PORT 8888
#define OPEN_MAX 5000

int main()
{
    int listenfd, connfd, sockfd, epfd;
    struct sockaddr_in serv_addr, clie_addr;
    socklen_t clie_addr_len;
    int ret, i, j, nready, nByte;
    char buf[BUFSIZ], str[BUFSIZ];
    struct epoll_event evt, ep[OPEN_MAX];

    listenfd = socket(AF_INET, SOCK_STREAM, 0);
    if(-1 == listenfd)
    {
        perror("socket error");
        exit(-1);
    }

    int opt = 1;
    setsockopt(listenfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    bzero(&serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERV_PORT);
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);

    ret = bind(listenfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
    if(-1 == ret)
    {
        perror("bind error");
        close(listenfd);
        exit(-1);
    }

    ret = listen(listenfd, 128);
    if(-1 == ret)
    {
        perror("listen error");
        close(listenfd);
        exit(-1);
    }
    printf("server is listening...\n");

    // 创建红黑树的根节点（使用数据结构：红黑树+就绪链表）
    epfd = epoll_create(OPEN_MAX);
    if(-1 == epfd)
    {
        perror("epoll_create error");
        close(listenfd);
        exit(-1);
    }

    evt.events = EPOLLIN;
    evt.data.fd = listenfd;

    ret = epoll_ctl(epfd, EPOLL_CTL_ADD, listenfd, &evt);
    if(-1 == ret)
    {
        perror("epoll_ctl error");
        close(listenfd);
        exit(-1);
    }

    while(1)
    {
        // 使用 epoll_wait 监听。若返回值大于 0，表明有
        // 满足条件的连接被监听到
        nready = epoll_wait(epfd, ep, OPEN_MAX, -1);
        if(nready < 0)
        {
            perror("select error");
            exit(-1);
        }

        for(i = 0; i < nready; ++i)
        {
            if(!(ep[i].events & EPOLLIN))
            {
                continue;
            }

            // 如果监听到的是 listenfd, 表明有新的请求进来
            if(ep[i].data.fd == listenfd)//如果是连接事件
            {
                clie_addr_len = sizeof(clie_addr);
                connfd = accept(listenfd, (struct sockaddr *)&clie_addr, &clie_addr_len);
                if(-1 == connfd)
                {
                    perror("accept error");
                    close(listenfd);
                    exit(-1);
                }
                printf("receive from %s from port %d\n",
                        inet_ntop(AF_INET, &clie_addr.sin_addr, str, sizeof(str)),
                        ntohs(clie_addr.sin_port));

                // 将 connfd 放在红黑树上继续监听
                evt.events = EPOLLIN;
                evt.data.fd = connfd;
                epoll_ctl(epfd, EPOLL_CTL_ADD, connfd, &evt);
            }

            else //不是连接建立事件，而是读写事件(信息传递事件)
            {
                sockfd = ep[i].data.fd;
                nByte = read(sockfd, buf, sizeof(buf));
                if(nByte == 0)
                {
                    ret = epoll_ctl(epfd, EPOLL_CTL_DEL, sockfd, NULL);
                    if(-1 == ret)
                    {
                        perror("epoll_ctl error");
                    }
                    close(sockfd);
                    printf("client[%d] closed connection\n", sockfd);
                }
                else if(nByte < 0)
                {   /* 连接异常 */
                    perror("epoll_ctl error");
                    ret = epoll_ctl(epfd, EPOLL_CTL_DEL, sockfd, NULL);
                    if(-1 == ret)
                    {
                        perror("epoll_ctl error");
                    }
                    close(sockfd);
                }
                else
                { /*正常操作*/
                    for(j = 0; j < nByte; ++j)
                    {
                        buf[j] = toupper(buf[j]);
                    }
                    write(sockfd, buf, nByte);
                    write(STDOUT_FILENO, buf, nByte);
                }
            }
        }
    }
    close(listenfd);
    close(connfd);
    return 0;
}
```

