## 类型转换

类对象与其他类型的转换：
- 由其他类型向自定义类型转换，一般称为**隐式转换**
- 由自定义类型向其他类型转换

由自定义类型向其他类型转换是由**类型转换函数**完成的，这是一个特殊的成员函数。形式如下：

```cpp
operator 目标类型()
{
    // ...
}
```

由自定义类型向其他类型转换的例子：

```cpp
#include <iostream>

using std::cout;
using std::endl;

class Complex {
public:
    friend std::ostream& operator << (std::ostream& os, const Complex& rhs);

    Complex(double dreal = 0, double dimag = 0)
    :_dreal(dreal), _dimag(dimag) {
        cout << "Complex(double = 0, double = 0)" << endl;
    }

    ~Complex() {
        cout << "~Complex()" << endl;
    }

private:
    double _dreal;
    double _dimag;
};

std::ostream& operator << (std::ostream& os, const Complex& rhs) {
    os << rhs._dreal << " + " << rhs._dimag << "i";
    return os;
}

class point {
public:
    friend std::ostream& operator << (std::ostream& os, const point& rhs);

    point(int x=0, int y=0):ix(x),iy(y) {
        cout << "point(int = 0, int = 0)" << endl;
    }

    ~point() {
        cout << "~point()" << endl;
    }

    point(const point& rhs):ix(rhs.ix), iy(rhs.iy) {
        cout << "point(const point&)" << endl;
    }

    operator int() {
        return ix + iy;
    }

    operator Complex() {
        return Complex(ix, iy);
    }

private:
    int ix;
    int iy;
};

std::ostream& operator << (std::ostream& os, const point& rhs){
    os << rhs.ix << " " << rhs.iy << endl;
    return os;
}


void test() {
    point pt4(4, 5);
    cout << "pt4 = " << pt4 << endl;

    int ix = pt4;
    cout << "ix = " << ix << endl;

    double dx = pt4;
    cout << "dx = " << dx << endl;

    Complex cx = pt4;
    cout << "cx = " << cx << endl;
}

int main() {
    test();
    return 0;
}
/*
point(int = 0, int = 0)
pt4 = 4 5

ix = 9
dx = 9
Complex(double = 0, double = 0)
cx = 4 + 5i
~Complex()
~point()
*/
```

## 嵌套类

一个类可以写在另一个类中，即**嵌套类**，又称**内部类**。

### 简单例子

```cpp
#include <iostream>

using std::cout;
using std::endl;

class Line {
public:
    Line(int x1, int y1, int x2, int y2)
    :_pt1(x1, y1), _pt2(x2, y2) {
        cout << "Line(int, int, int, int)" << endl;
    }

    ~Line() {
        cout << "~Line()" << endl;
    }

    void print() const {
        _pt1.print();
        cout << " ---> ";
        _pt2.print();
        cout << endl;
    }

private:
    class point {
    public:
        point(int x=0, int y=0):ix(x),iy(y) {
            cout << "point(int = 0, int = 0)" << endl;
        }

        void print() const {
            std::cout << ix << " "
                      << iy ;
        }

        ~point() {
            cout << "~point()" << endl;
        }

    private:
        int ix;
        int iy;
    };

private:
    point _pt1;
    point _pt2;
};

int main() {
    Line line(1, 2, 3, 4);
    cout << "line = ";
    line.print();
}
/*
point(int = 0, int = 0)
point(int = 0, int = 0)
Line(int, int, int, int)
line = 1 2 ---> 3 4
~Line()
~point()
~point()
*/
```

### 设计模式 Pimpl

通过一个私有的成员指针，隐藏指针所指向类的内部实现。该设计模式有以下优点：
- 提高编译速度
- 信息隐藏
- 减小编译依赖，以小代价平滑升级库文件
- 接口与实现解耦
- 移动语义友好

```cpp
//Line.h
class Line {
public:
    Line(int,int,int,int);
    ~Line();
    void printLine() const;

private:
    class LineImpl; //类的前向声明
    LineImple* _pimpl;
};
```

```cpp
//Line.cc
#include "Line.h"

class Line::LineImpl {
public:
    LineImpl(int x1, int y1, int x2, int y2);
    void printLineImpl() const;

private:
    class Point {
    public:
        Point(int x = 0, int y = 0): _x(x), _y(y) {}
        void print() const;

    private:
        int _x;
        int _y;
    };

    Point _pt1;
    Point _pt2;
};

Line::LineImpl::LineImpl(int x1, int y1, int x2, int y2)
                        : _pt1(x1, y1) ,_pt2(x2, y2) {}

void Line::LineImpl::printLineImpl() const {
    _pt1.print();
    cout << " ---> ";
    _pt2.print();
    cout << endl;
}

Line::Line(int x1, int y1, int x2, int y2)
          : _pimpl(new LineImpl(x1, y1, x2, y2)) {}

Line::~Line() {
    delete _pimpl;
}

void Line::printLine() const {
    pimpl->printLineImpl();
}
```

