## 单例模式的自动释放

### 使用友元形式进行设计

```cpp
#include <iostream>

using std::cout;
using std::endl;

class A{
    friend class AutoRelease;
public:
    static A* myCreateObj(){
        if(_ptmp == nullptr){
            _ptmp = new A();
        }
        return _ptmp;
    }

private:
    ~A(){
        cout << "~A()" << endl;
    }

    A(){
        cout << "A()" << endl;
    }
    static A* _ptmp;
};

A* A::_ptmp = nullptr;

class AutoRelease {
public:
    AutoRelease() {
        cout << "AutoRelease()" << endl;
    }

    ~AutoRelease() {
        cout << "~AutoRelease()" << endl;
        if(A::_ptmp == nullptr) return;
        delete A::_ptmp;
        A::_ptmp = nullptr;
    }
};

int main(){
    A* ps1 = A::myCreateObj();
    cout << "ps1 = " << ps1 << endl;

    AutoRelease ar;
    return 0;
}
/*
A()
ps1 = 0x563e22a51eb0
AutoRelease()
~AutoRelease()
~A()
*/
```

