### 实现写时复制

大致写出写时复制的逻辑。大体思路：

![66-5.png](https://s2.loli.net/2024/02/21/R12D7ptInwiuEBd.png)

```cpp
#include <iostream>
#include <string.h>

using std::cout;
using std::endl;
using std::ostream;

class String{
    friend ostream& operator << (ostream& os, const String& rhs);
public:
    String():_pstr(new char[5]()+4) {
        cout << "String()" << endl;
        initRefCount();
    }

    String(const char* pstr)
    :_pstr(new char[strlen(pstr)+5]()+4) {
        cout << "String(const char*)" << endl;
        strcpy(_pstr, pstr);
        initRefCount();
    }

    String(const String& rhs):_pstr(rhs._pstr) {
        cout << "String(const String&)" << endl;
        increseRefCount();
    }

    String& operator = (const String& rhs) {
        cout << "String& operator = (const String&)" << endl;
        if(this == &rhs) return *this;

        decreseRefCount();
        if(0 == getRefCount()) {
            delete [] (_pstr-4);
        }

        _pstr = rhs._pstr; // 浅拷贝
        increseRefCount();

        return *this;
    }

    int getRefCount() const {
        return *(int*)(_pstr-4);
    }

    const char* c_str() const {
        return _pstr;
    }

private:
    class CharProxy {
    public:
        CharProxy(String& self, size_t idx)
                 : _self(self), _idx(idx) {}

        char& operator = (const char& ch);

        friend ostream& operator << (ostream& os, const CharProxy& rhs);

    private:
        String& _self;
        size_t _idx;
    };

public:
    CharProxy operator [] (size_t idx) {
        return CharProxy(*this, idx);
    }

    ~String() {
        cout << "~String()" << endl;
        decreseRefCount();
        if(0 == getRefCount()) {
            delete [] (_pstr-4);
        }
    }

    // 双重友元
    friend ostream& operator << (ostream& os, const String::CharProxy& rhs);

private:
    void initRefCount() {
        *(int*)(_pstr-4) = 1; // 引用计数
    }

    void increseRefCount() {
        ++ *(int*)(_pstr-4);
    }

    void decreseRefCount() {
        -- *(int*)(_pstr-4);
    }

    size_t size() const {
        return strlen(_pstr);
    }

    char* _pstr;
};

ostream& operator << (ostream& os, const String& rhs) {
    if(rhs._pstr) {
        os << rhs._pstr;
    }
    return os;
}

// input
char& String::CharProxy::operator = (const char& ch) {
    if(_idx >= _self.size()) {
        static char charNull = '\0';
        return charNull;
    }
    if(_self.getRefCount() > 1) {
        char* tmp = new char[_self.size()+5]()+4;
        strcpy(tmp, _self._pstr);
        _self.decreseRefCount();

        _self._pstr = tmp;
        _self.initRefCount();
    }
    _self._pstr[_idx] = ch;  // 进行写操作
    return _self._pstr[_idx];
}

// output
ostream& operator << (ostream& os, const String::CharProxy& rhs) {
    os << rhs._self._pstr[rhs._idx];
    return os;
}

int main() {
    String s1("hello");
    cout << "s1 = " << s1 << endl;
    cout << "s1.getRefCount = " << s1.getRefCount() << endl;
    printf("s1' address = %p\n", s1.c_str());

    cout << endl;
    String s2 = s1;
    cout << "s1 = " << s1 << endl;
    cout << "s2 = " << s2 << endl;
    cout << "s1.getRefCount = " << s1.getRefCount() << endl;
    cout << "s2.getRefCount = " << s2.getRefCount() << endl;
    printf("s1' address = %p\n", s1.c_str());
    printf("s2' address = %p\n", s2.c_str());

    cout << endl;
    String s3("world");
    cout << "s3 = " << s3 << endl;
    cout << "s3.getRefCount = " << s3.getRefCount() << endl;
    printf("s3' address = %p\n", s3.c_str());

    cout << endl;
    s3 = s1;
    cout << "s1 = " << s1 << endl;
    cout << "s2 = " << s2 << endl;
    cout << "s3 = " << s3 << endl;
    cout << "s1.getRefCount = " << s1.getRefCount() << endl;
    cout << "s2.getRefCount = " << s2.getRefCount() << endl;
    cout << "s3.getRefCount = " << s3.getRefCount() << endl;
    printf("s1' address = %p\n", s1.c_str());
    printf("s2' address = %p\n", s2.c_str());
