#include <cstdint>
#include <unordered_set>

using std::cout;
using std::endl;
using std::unordered_multiset;

class point{
	friend std::ostream& operator << (std::ostream& os, const point& rhs);
public:
    explicit point(int x=0, int y=0):ix(x),iy(y) {}
    void print(){
        std::cout << ix << " "
                  << iy << std::endl;
    }
    ~point() {}
    point(const point& rhs):ix(rhs.ix), iy(rhs.iy) {}
	int getX() const {
		return ix;
	}
	int getY() const {
		return iy;
	}
private:
    int ix;
    int iy;
};

struct HashPoint {
	std::uint64_t operator () (const point& rhs) const {
		// 设计哈希函数
		cout << "we've hashed here" << endl;
		return (rhs.getX() << 1) ^ (rhs.getY() << 2);
	}
};

struct EqualToPoint
{
	bool operator () (const point& lhs, const point& rhs) const
	{
		cout << "kafaka2." << endl;
		return (lhs.getX() == rhs.getX())
			   && (lhs.getY() == rhs.getY());
	}
};

std::ostream& operator << (std::ostream& os, const point& rhs) {
	os << "(" << rhs.ix
	   << ", " << rhs.iy << ")";
	return os;
}

template <typename Container>
void display(const Container& con)
{
    for(auto &elem : con)
    {
        cout << elem << "  ";
    }
    cout << endl;
}

void test() {
	unordered_multiset<point, HashPoint, EqualToPoint> number = {
		point(4, 5),
		point(1, 2),
		point(-1, 2),
		point(1, -2),
		point(1, 2),
		point(3, 2),
		point(8, 10),
	};
	display(number);
}

int main() {
	test();
	return 0;
}
/*
we've hashed here
we've hashed here
we've hashed here
we've hashed here
we've hashed here
kafaka2.
we've hashed here
we've hashed here
(-1, 2)  (1, -2)  (1, 2)  (1, 2)  (8, 10)  (3, 2)  (4, 5)
*/
```

unordered_map 和 unordered_multimap 大体上和上面思路相同。

针对 string 而言，已经实现了 hash ，所以就不需要再进行 hash 函数的设计。

