## 拷贝构造函数

默认情况下，编译器会自动生成拷贝构造函数。

来看下面的例子：

```cpp
// testComputer.cc
#include "Computer.h"
#include <iostream>

using std::cout;
using std::endl;

void test(){
    Computer com("lenovo", 5300);
    com.print();
    cout << endl;

    Computer com2 = com;
    com2.print();
    cout << endl;
}

int main(){
    test();
    return 0;
}
/*
Computer(const char*, float)
name = lenovo
price = 5300

name = lenovo
price = 5300

~Computer()
1111
~Computer()
1111
free(): double free detected in tcache 2
Aborted (core dumped)
*/
```

在语句``Computer com2 = com;``中，调用了拷贝构造函数。程序报错的原因等会再讲。

拷贝构造函数的逻辑（以某个具体的类为例）：

```cpp
Point(const Point& rhs):_ix(rhs._ix),_iy(rhs._iy){}
```

而上面的程序出错点在于：数据成员是指针类型，拷贝过来的指针指向了同一地址，因此销毁的时候对同一地址 free 了两次。

``Computer.h``文件部分代码：

```cpp
class Computer{
public:
    Computer(const char* name, float price);
    void setBrand(const char* name);
    void setPrice(float price);
    void print();
    ~Computer();

private:
    char* _name;
    float _price;
};
```

``Computer.cc``文件部分代码：

```cpp
Computer::Computer(const char* name, float price)
                  :_name(new char[strlen(name)+1]()),_price(price){
    cout << "Computer(const char*, float)" << endl;
    strcpy(_name, name);
}

Computer::~Computer(){
    cout << "~Computer()" << endl;
    if(_name){ // 等价于 if(_name != nullptr)
        cout << "1111" << endl; // for presentation
        delete [] _name;
        _name = nullptr;
    }
}
```

可以改为：

```cpp
// Computer.h
#ifndef _Computer_H_
#define _Computer_H_

#include <iostream>

using std::cout;
using std::endl;

class Computer{
public:
    Computer(const char* name, float price);
    void setBrand(const char* name);
    void setPrice(float price);
    void print();
    ~Computer();
    Computer(const Computer& rhs);
private:
    char* _name;
    float _price;
};

#endif
```

```cpp
// Computer.cc
#include "Computer.h"
#include <cstring>

Computer::Computer(const char* name, float price)
                  :_name(new char[strlen(name)+1]()),_price(price){
    cout << "Computer(const char*, float)" << endl;
    strcpy(_name, name);
}

void Computer::setBrand(const char* name){
    strcpy(_name, name);
}

void Computer::setPrice(float price){
    _price = price;
}

void Computer::print(){
    cout << "name = " << _name << endl
         << "price = " << _price << endl;
}

Computer::Computer(const Computer& rhs)
                   :_name(new char[strlen(rhs._name)+1]()), _price(rhs._price){
    strcpy(_name, rhs._name);
}

Computer::~Computer(){
