    }

    String(const char* pstr):
    _pstr(new char[strlen(pstr)+1]())
    {
        cout << "String(const char*)" << endl;
        strcpy(_pstr, pstr);
    }

    String(const String& rhs):
    _pstr(new char[strlen(rhs._pstr)+1]())
    {
        cout << "String(const String&)" << endl;
        strcpy(_pstr, rhs._pstr);
    }

    String& operator= (const String& rhs){
        cout << "String& operator= (const String&)" << endl;
        if(this != &rhs){  //防止自复制
            if(_pstr){
                delete [] _pstr;
                _pstr = nullptr;
            }

            _pstr = new char[strlen(rhs._pstr)+1]();
            strcpy(_pstr, rhs._pstr);
        }
        return *this;
    }

    size_t length() const{
        size_t len = 0;
        if(_pstr){
            len = strlen(_pstr);
        }
        return len;
    }

    const char* c_str() const{
        if(_pstr){
            return _pstr;
        }
        else return nullptr;
    }

    ~String(){
        cout << "~String()" << endl;
        if(_pstr){
            delete [] _pstr;
            _pstr = nullptr;
        }
    }

    void print() const{
        if(_pstr){
            cout << "_pstr = " << _pstr << endl;
        }
    }

private:
    char* _pstr;
};

int main(int argc, char* argv[]){
    String str1;
    str1.print();

    cout << endl;
    String str2 = "hello world";
    String str3("Mizuho");

    cout << endl;
    str2.print();
    str3.print();

    cout << endl;
    String str4 = str3;
    str4.print();

    str4 = str2;
    str4.print();

    const char* pstr = str3.c_str();

    return 0;
}
```

