### 自增自减

前置和后置``++``：

```cpp
#include <iostream>
#include <limits>

using std::cout;
using std::endl;

class Complex{
friend Complex operator + (const Complex& lhs, const Complex& rhs);
public:
    Complex(double dreal = 0, double dimag = 0)
    :_dreal(dreal), _dimag(dimag){
        cout << "Complex(double = 0, double = 0)" << endl;
    }

	Complex& operator += (const Complex& rhs){
		cout << "Complex& operator +=(const Complex&)" << endl;
		_dreal += rhs._dreal;
		_dimag += rhs._dimag;
		return *this;
	}

	Complex& operator ++ (){ // 前置 ++
		cout << "Complex& operator ++()" << endl;
		++_dreal;
		++_dimag;
		return *this;
	}

	Complex operator ++ (int){ // 这里的 int 是标志位，用于区分
		cout << "Complex operator ++ (int)" << endl;
		Complex tmp(*this);
		_dreal++;
		_dimag++;
		return tmp;
	}

    void print() const{
        cout << _dreal << " + " << _dimag << "i" << endl;
    }

    ~Complex(){
        cout << "~Complex()" << endl;
    }

private:
    double _dreal;
    double _dimag;
};

Complex operator + (const Complex& lhs, const Complex& rhs){
    cout << "friend Complex operator + (const Complex&, const Complex&)" << endl;
    return Complex(lhs._dreal + rhs._dreal,
                   lhs._dimag + rhs._dimag);
}

int main(){
    Complex c1(1, 2);
    cout << "c1 = ";
    c1.print();

    cout << endl << endl;
    Complex c2(3, 4);
    cout << "c2 = ";
    c2.print();

    cout << endl << endl;
    Complex c3 = c1 + c2;
    cout << "c3 = ";
    c3.print(); // 4+6i

    cout << endl << endl;
    cout << "(++c3) = ";
    (++c3).print();
	cout << "c3 = ";
	c3.print();

    cout << endl << endl;
    cout << "(c3++) = ";
	(c3++).print();
	cout << "c3 = ";
	c3.print();

    return 0;
}
/*
c1 = 1 + 2i


Complex(double = 0, double = 0)
c2 = 3 + 4i


friend Complex operator + (const Complex&, const Complex&)
Complex(double = 0, double = 0)
c3 = 4 + 6i


(++c3) = Complex& operator ++()
5 + 7i
c3 = 5 + 7i


(c3++) = Complex operator ++ (int)
5 + 7i
~Complex()
c3 = 6 + 8i
~Complex()
~Complex()
~Complex()
*/
```

前置``++``返回的是对象的引用，是左值，可以取地址；后置``++``返回的是局部对象，是右值，不能取地址。

前置``++``的效率比后置``++``高。

### 输出流运算符

对于重载输出流运算符而言，不能写成成员函数的形式，因为不能改变操作数的顺序。推荐使用友元：

```cpp
#include <iostream>
#include <limits>

using std::cout;
using std::endl;

class Complex{
public:
    friend std::ostream& operator << (std::ostream& os, const Complex& rhs);

    Complex(double dreal = 0, double dimag = 0)
    :_dreal(dreal), _dimag(dimag){
        cout << "Complex(double = 0, double = 0)" << endl;
    }

    ~Complex(){
        cout << "~Complex()" << endl;
    }

private:
    double _dreal;
    double _dimag;
};

std::ostream& operator << (std::ostream& os, const Complex& rhs){
    os << rhs._dreal << " + " << rhs._dimag << "i";
    return os;
}

int main(){
    Complex c1(1, 2);
    cout << "c1 = " << c1 << endl;
    return 0;
}
/*
Complex(double = 0, double = 0)
c1 = 1 + 2i
~Complex()
*/
```

关于下面这句：

```cpp
cout << "c1 = " << c1 << endl;
```

也可以写为：

```cpp
operator<<(operator<<(cout, "c1 = "), c1).operator<<(endl);
```

