void readDouble(std::istream& is, double& rhs){
    while(is >> rhs, !is.eof()){
        if(is.bad()){
            std::cerr << "istream is bad." << endl;
            return;
        }
        else if(is.fail()){
            is.clear();
            is.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            cout << "please input a double-type number : ";
        }
        else break;
    }
}

