### 成员访问运算符

成员访问运算符包括：``->``、``*``。

``->``只能以成员函数的形式重载，其返回值必须是一个指针或是重载了``->``的对象。

来看``->``的例子：

```cpp
#include <iostream>

using std::cout;
using std::endl;

class Data {
public:
    Data(int data = 0):_data(data) {
        cout << "Data(int = 0)" << endl;
    }

    int get_data() const {
        return _data;
    }

    ~Data() {
        cout << "~Data()" << endl;
    }

private:
    int _data;
};

class secondLayyer {
public:
    secondLayyer(Data* pdata):_pdata(pdata) {
        cout << "secondLayyer(Data*)" << endl;
    }

    ~secondLayyer() {
        cout << "~secondLayyer()" << endl;
        if(_pdata){
            delete _pdata;
            _pdata = nullptr;
        }
    }

    Data* operator -> () {
        return _pdata;
    }

private:
    Data* _pdata;
};

class thirdLayyer {
public:
    thirdLayyer(secondLayyer* ps1):_ps1(ps1) {
        cout << "thirdLayyer(secondLayyer*)" << endl;
    }

    secondLayyer& operator -> () {
        return *_ps1;
    }

    ~thirdLayyer() {
        cout << "~thirdLayyer()" << endl;
        if(_ps1){
            delete _ps1;
            _ps1 = nullptr;
        }
    }

private:
    secondLayyer* _ps1;
};

void test() {
    secondLayyer sl(new Data(10)); // 栈对象
    cout << "sl->get_data() = " << sl->get_data() << endl;
    // 勤劳的编译器使我们可以在上面的写法中省略一个箭头
    // 等价的写法： 
    cout << "s1->get_data() = " << sl.operator->()->get_data() << endl;
}

int main() {
    test();
    return 0;
}
/*
Data(int = 0)
secondLayyer(Data*)
sl->get_data() = 10
s1->get_data() = 10
~secondLayyer()
~Data()
*/
```

