### 总结：单链表的全部操作

```cpp
struct LNode{
  ElemType data;
  LNode* next;
};

bool InitList(LNode*& L){
  L = (LNode*) malloc(sizeof(LNode));  //分配一个头节点
  if(L==NULL) return false;    //内存不足，分配失败
  L->next = NULL;             //头节点之后暂时还没有节点
  return true;
}

bool isEmpty(LNode* L){
  if(L->next==NULL)
    return true;
  else
    return false;
}

void work(){  //或者认为是 main() 函数也勉强可以
  LNode* L;
  InitList(L);
  // ...
}

bool InsertNextNode(LNode* p, ElemType e){ //指定节点的后插操作
  if(p==NULL)
    return false;
  LNode* s = (LNode*) malloc(sizeof(LNode));
  s->data = e;
  s->next = p->next;
  p->next = s;
  return true;
}

//思路：使用后插，然后交换数据成员的内容
bool InsertPreNode(LNode* p, ElemType e){  //指定节点的前插操作
  if(p==NULL)
    return false;
  LNode* s = (LNode*) malloc(sizeof(LNode));
  if(s==NULL) //内存分配失败，考试可以不写
    return false;
  s->next = p->next;
  p->next = s;
  s->data = p->data;
  p->data = e;
  return true;
}

//按位查找，返回第i个元素的指针
LNode* GetElem(LNode*& L, int i){
  if(i<0)
    return NULL;
  LNode* p;  //指向当前扫描到的节点
  int j = 0; //当前p指向的是第几个节点
  p = L;  //指向头节点
  while(p!=NULL && j<i){
    p = p->next;
    j++;
  }
  return p;
}

LNode* LocateElem(LNode*& L, ElemType e){ //按值查找
  LNode* p = L->next;
  while(p!=NULL && p->data!=e)  //注意细节，往上翻
    p = p->next;
  return p;
}

//插入完成后新元素的位置为 i
bool ListInsert(LNode*& L, int i, ElemType e){ //按位序插入
  if(i<1)
    return false;
  LNode* p = GetElem(L, i-1);
  return InsertNextNode(p, e);
}

bool ListDelete(LNode*& L, int i, ElemType &e){ //按位序删除
  if(i<1)
    return false;
  LNode* p = GetElem(L, i-1);
  if(p==NULL)  // i 值不合法
    return false;
  if(p->next==NULL) //第i-1个节点之后已无其他节点
    return false;
  LNode* q = p->next; //令q指向被删除节点
  e = q->data; //用e返回元素的值
  p->next = q->next;
  free(q);
  return true;
}

//删除指定节点 p
bool DeleteNode(LNode* p){
  if(p==NULL)
    return false;
  LNode* q = p->next;
  p->data = p->next->data;
  p->next = q->next;
  free(q);
  return true;
}

int Length(LNode*& L){ //求表的长度
  int len = 0;
  LNode* p = L;
  while(p->next!=NULL){
    p = p->next;
    len++;
  }
  return len;
}

LNode* List_TailInsert(LNode*& L){ //尾插法建立单链表
  int x;
  L = (LNode*) malloc(sizeof(LNode));
  LNode *s, *r=L;  // r 指向最后一个元素
  scanf("%d",&x);
  while(x!=9999){ // 9999是退出值
    s = (LNode*) malloc(sizeof(LNode));
    s->data = x;
    r->next = s;
    r = s;
    scanf("%d",&x);
  }
  r->next = NULL;
  return L;
}

void List_HeadInsert(LNode*& L){ //头插法建立单链表
  InitList(L);
  int x;
  scanf("%d",&x);
  while(x!=9999){ //9999 为退出值，当然也可以while(scanf("%d",&x)){} ，看具体情况
    InsertNextNode(L, x);
    scanf("%d",&x);
  }
  return;
}
