Dijkstra 算法（用于求单源最短路径）：
- **要求图的边权为正**
- 可以求环
- 时间复杂度：
  - 考试中可认为（也就是未优化的算法版本）复杂度是 $O(n^2)$
  - 若用二叉堆（C++ STL ``priority_queue``）维护 dist 数组，最终可以得到 $O((m+n)\log n)$ 的复杂度

![46-74.png](https://bu.dusays.com/2023/08/26/64e9769b23a1f.png "Dijkstra算法执行流程")

```cpp
// Dijkstra
#include<cstdio>
#include<queue>
#define MAXM 200010
#define MAXN 100010
using namespace std;

const int INF =2147483647;
int n,m,s,dis[MAXN];
bool done[MAXN];
int tot,head[MAXN];
struct Edge{int v,w,next;}edge[MAXM];

inline void addedge(int x,int y,int z)
{
    edge[++tot].v=y;
    edge[tot].w=z;
    edge[tot].next=head[x];
    head[x]=tot;
}

struct node{
    int u,dist;
    bool operator<(const node& v)const{
        return dist>v.dist;
    }
};

priority_queue<node> qwq;
inline void dijkstra()
{
    for(int i=1;i<=n;i++)dis[i]=INF;
    dis[s]=0;
    qwq.push((node){s,0});

    while(!qwq.empty())
    {
        node front=qwq.top(); qwq.pop();
        int u=front.u,dist=front.dist;
        if(done[u])continue;
        done[u]=true;
        for(int i=head[u];i;i=edge[i].next)
        {
            int y=edge[i].v,z=edge[i].w;
            if(dis[u]+z<dis[y])
            {
                dis[y]=dis[u]+z;
                qwq.push((node){y,dis[y]});
            }
        }
    }
}

int main()
{
    scanf("%d%d%d",&n,&m,&s);
    int x,y,z;
    for(int i=1;i<=m;i++){
        scanf("%d%d%d",&x,&y,&z);
        addedge(x,y,z);
    }

    dijkstra();

    for(int i=1;i<=n;i++)printf("%d ",dis[i]);
    return 0;
}
```

