### 折半查找

二分查找的实现细节需要特别注意，在某些特殊的情况下，不正确的写法会导致死循环或是其他的错误。王道的代码就是错误的。

我们直接来看正确的做法：总是将查找区间设为左闭右开的。以题目[P1824 进击的奶牛](https://www.luogu.com.cn/problem/P1824)为例，该题的做法是二分答案，给出代码如下：

```cpp
#include<iostream>
#include<algorithm>
using namespace std;
int a,b,p[1000010];

inline bool check(int x)
{
    int cnt=0,pre=-1500000000;
    for(int i=1;i<=a;i++)
    {
        if(p[i]-pre>=x){
            cnt++;
            pre=p[i];
        }
    }
    if(cnt>=b)return true;
    else return false;
}

int main()
{
    cin>>a>>b;
    for(int i=1;i<=a;i++)cin>>p[i];
    sort(p+1,p+1+a);

    int left=0,right=0x7fffffff;
    while(right!=left+1)
    {
        int mid=(left+right)>>1;
        if(check(mid))left=mid;
        else right=mid;
    }

    cout<<left;
    return 0;
}
```

