```cpp
// 王道的代码
BSTNode* BSTsearch(BSTree T, int key) {
  if(T==NULL)
    return NULL;   //查找失败
  if(key==T->key)
    return T;      //查找成功
  else if (key < T->key)
    return BSTsearch(T->lchild, key);  //在左子树中查找
  else
    return BSTsearch(T->rchild, key);  //在右子树中查找
}
//最坏空间复杂度为 O(h) ，h 为树的高度
```

