// 建立大根堆
void build_maxHeap(int A[], int len){
  for(int i=len/2; i>0; i--)
    headAdjust(A, i, len);
}

// 将以 k 为根的子树调整为大根堆
void headAdjust(int A[], int k, int len){
  A[0] = A[k]; // A[0] 暂存子树的根节点
  for(int i=2*k; i<=len; i*=2){
    if(i<len && A[i]<A[i+1]) i++; // 选取 key 较大的子节点的下标
    if(A[0]>=A[i]) break;
    else {
      A[k] = A[i];
      k = i;
    }
  }
  A[k] = A[0];
}
```

