//严重错误：这个函数试图返回局部对象的引用
const string &manip(){
    string ret;
    //以某种方式改变一下ret
    if(!ret.empty())
        return ret;     //错误！返回局部对象的引用
    else
        return "Empty"; //错误！"Empty"是一个局部临时变量
}
