## 强连通分量缩点

题目描述：https://www.luogu.org/problemnew/show/P3387

```cpp
#include<cstdio>
#define MAX(a,b) ((a)>(b)?(a):(b))
#define MIN(a,b) ((a)<(b)?(a):(b))
using namespace std;

const int maxn=1e4+3;
const int maxm=1e5+3;
struct Edge{int v,next;};
Edge edge[maxm],edge2[maxm];
int head[maxn],w[maxn],dfn[maxn],low[maxn],stac[maxn],color[maxn];
int n,m,tot,num,top,cnt,ans;
int head2[maxn],W[maxn],tot2,sum[maxn];
bool ins[maxn];

inline void addedge(int x,int y){
    edge[++tot].v=y;
    edge[tot].next=head[x];
    head[x]=tot;
}

inline void addedge2(int x,int y){
    edge2[++tot2].v=y;
    edge2[tot2].next=head2[x];
    head2[x]=tot2;
}

inline void input(){
    scanf("%d%d",&n,&m);
    for(int i=1;i<=n;i++)scanf("%d",&w[i]);
    for(int i=1;i<=m;i++){
        int x,y;
        scanf("%d%d",&x,&y);
        addedge(x,y);
    }
}

int dfs(int x){
    if(sum[x])return sum[x];
    int temp=0;
    for(int i=head2[x];i;i=edge2[i].next){
        temp=MAX(temp,dfs(edge2[i].v));
    }
    sum[x]=W[x]+temp;
    return sum[x];
}

void tarjan(int x){
    low[x]=dfn[x]=++num;
    stac[++top]=x; ins[x]=true;
    for(int i=head[x];i;i=edge[i].next){
        int y=edge[i].v;
        if(!dfn[y]){
            tarjan(y);
            low[x]=MIN(low[x],low[y]);
        }
        else if(ins[y]){
            low[x]=MIN(low[x],dfn[y]);
        }
    }
    if(dfn[x]==low[x]){
        ++cnt; int y;
        do{
            y=stac[top--]; ins[y]=false;
            color[y]=cnt;
            W[cnt]+=w[y];
        }while(x!=y);
    }
}

int main(){
    input();
    for(int i=1;i<=n;i++){
        if(!dfn[i])tarjan(i);
    }

    for(int x=1;x<=n;x++){
        for(int i=head[x];i;i=edge[i].next){
            int y=edge[i].v;
            if(color[x]!=color[y]){
                addedge2(color[x],color[y]);
            }
        }
    }
    for(int i=1;i<=cnt;i++){
        if(!sum[i]){
            ans=MAX(ans,dfs(i));
        }
    }

    printf("%d",ans);
    return 0;
}
