## 非压位高精

虽然重载的运算符两边数据类型都是Bigint，但因为自动强制转换，所以用[Bigint] * [int]也不会错。

在大数除int、大数对int取余时，效率不及专门功能的函数

参考：CSDN用户 代号4101

```cpp
#include<iostream>
#include<string>
#include<cstring>
#include<cstdio>
#define MAX(a,b) ((a)>(b)?(a):(b))
using namespace std;

const int MAXLEN = 1000;  //最长的数字长度

struct Bigint{
    int d[MAXLEN],len;
    void clean(){while(len>1&&!d[len-1])len--;} //去前导0

    Bigint(){memset(d,0,sizeof(d));len=1;}
    Bigint(int num){*this=num;}
    Bigint(char* num){*this=num;}

    Bigint operator = (const char* num){
        len=strlen(num);
        for(int i=0;i<len;i++)d[i]=num[len-1-i]-'0';
        clean();
        return *this;
    }

    Bigint operator = (int num){
        char s[MAXLEN];
        sprintf(s,"%d",num);
        *this=s;
        return *this;
    }

    Bigint operator + (const Bigint& b){ //只能大数加小数
        Bigint c=*this; int i;
        for(i=0;i<b.len;i++){
            c.d[i]+=b.d[i];
            if(c.d[i]>9)c.d[i]%=10,c.d[i+1]++;
        }
        while(c.d[i]>9)c.d[i++]%=10,c.d[i]++;
        c.len=MAX(len,b.len);
        if(c.d[i]&&c.len<=i)c.len=i+1;
        return c;
    }

    Bigint operator - (const Bigint& b){ //不能用小数减大数
        Bigint c=*this; int i;
        for(i=0;i<b.len;i++){
            c.d[i]-=b.d[i];
            if(c.d[i]<0)c.d[i]+=10,c.d[i+1]--;
        }
        while(c.d[i]<0)c.d[i++]+=10,c.d[i]--;
        c.clean();
        return c;
    }

    Bigint operator * (const Bigint& b)const{
        int i,j; Bigint c;
        c.len=len+b.len;
        for(j=0;j<b.len;j++)
            for(i=0;i<len;i++)
                c.d[i+j]+=d[i]*b.d[j];
        for(i=0;i<c.len-1;i++)
            c.d[i+1]+=c.d[i]/10,c.d[i]%=10;
        c.clean();
        return c;
    }

    Bigint operator / (const Bigint& b){
        int i,j;
        Bigint c=*this,a=0;
        for(i=len-1;i>=0;i--){
            a=a*10+d[i];
            for(j=0;j<10;j++)if(a<b*(j+1))break;
            c.d[i]=j;
            a=a-b*j;
        }
        c.clean();
        return c;
    }

    Bigint operator % (const Bigint& b){
        int i,j; Bigint a=0;
        for(i=len-1;i>=0;i--){
            a=a*10+d[i];
            for(j=0;j<10;j++)if(a<b*(j+1))break;
            a=a-b*j;
        }
        return a;
    }

    Bigint operator += (const Bigint& b){
        *this=*this+b;
        return *this;
    }

    bool operator < (const Bigint& b)const{
        if(len!=b.len)return len<b.len;
        for(int i=len-1;i>=0;i--)
            if(d[i]!=b.d[i])return d[i]<b.d[i];
        return false;
    }

    bool operator > (const Bigint& b)const{return b<*this;}
    bool operator <= (const Bigint& b)const{return !(b<*this);}
    bool operator >= (const Bigint& b)const{return !(*this<b);}
    bool operator != (const Bigint& b)const{return b<*this||*this<b;}
    bool operator == (const Bigint& b)const{return !(b<*this)&&!(b>*this);}

    string str()const{
        char s[MAXLEN]={};
        for(int i=0;i<len;i++)s[len-1-i]=d[i]+'0';
        return s;
    }
};

istream& operator >> (istream& in,Bigint& x){
    string s; in>>s;
    x=s.c_str();
    return in;
}

ostream& operator << (ostream& out,const Bigint& x){
    out<<x.str();
    return out;
}

int main(){     //just an example...
    Bigint s=0,t;
	while(cin>>t){
		if(t.len==1&&!t.d[0])break;
		s=s+t;
	}
	cout<<s<<endl;
	return 0;
}
```

